"""Pixel Arena level pathing: bots walk a tile map painted in primary colors."""

import heapq

Cell = tuple[int, int]  # (row, col)

_ENTER_COST: dict[str, int] = {".": 1, "D": 3, "S": 1, "G": 1}


def _locate_marker(grid: list[str], marker: str) -> Cell | None:
    for r, row in enumerate(grid):
        c = row.find(marker)
        if c != -1:
            return (r, c)
    return None


def find_path(grid: list[str]) -> list[Cell] | None:
    """Cheapest 4-neighbour path from 'S' to 'G', both inclusive.

    '.' floor costs 1 to enter, 'D' door costs 3, '#' is a wall, 'S'/'G' cost 1.
    Return None when G is unreachable.
    """
    start = _locate_marker(grid, "S")
    goal = _locate_marker(grid, "G")
    if start is None or goal is None:
        return None

    best: dict[Cell, int] = {start: 0}
    prev: dict[Cell, Cell] = {}
    heap: list[tuple[int, Cell]] = [(0, start)]
    while heap:
        cost, cur = heapq.heappop(heap)
        if cost > best.get(cur, cost):
            continue
        if cur == goal:
            path = [cur]
            while path[-1] != start:
                path.append(prev[path[-1]])
            path.reverse()
            return path
        r, c = cur
        for nr, nc in ((r - 1, c), (r + 1, c), (r, c - 1), (r, c + 1)):
            if nr < 0 or nr >= len(grid) or nc < 0 or nc >= len(grid[nr]):
                continue
            step = _ENTER_COST.get(grid[nr][nc])
            if step is None:
                continue
            ncost = cost + step
            if ncost < best.get((nr, nc), ncost + 1):
                best[(nr, nc)] = ncost
                prev[(nr, nc)] = cur
                heapq.heappush(heap, (ncost, (nr, nc)))
    return None

